using Godot;
using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
namespace Arconist.GodotApp;
// Headless production-resource/node/projection tests, never graphical qualification.
public static class ArcTapValidation
{
 private sealed class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
 public static void Run(Node owner,SpatialTrack track,string evidenceDir)
 {
  int passed=0,failed=0;var outcomes=new List<object>();
  void Check(bool ok,string why){if(!ok)throw new Exception(why);}
  void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});GD.Print("PASS R008 "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});GD.Print("FAIL R008 "+name+": "+e.Message);}}
  string Load(string n)=>Godot.FileAccess.GetFileAsString("res://content/"+n);
  Kernel New(){var k=new Kernel(Chart.Parse(Load("native_arc_tap.aff")));k.Frame(0);k.Frame(3002);return k;}
  void F(Kernel k,int e)=>k.Frame(e+3002);
  SkyContact Pick(ArcTapState child){var p=child.WorldPosition;var screen=track.Camera.UnprojectPosition(SpatialTrack.World(p.X,p.Y,p.Z));Check(track.PickSky(screen,out var sky),"child screen ray");return sky;}
  Test("all twelve chart resources load from real Godot filesystem",()=>{foreach(string n in new[]{"practice.aff","ordinary_two_tap.aff","mixed_practice.aff","native_hold.aff","hold_first.aff","tap_first.aff","audible_practice.aff","audible_aff120.aff","sky_practice.aff","native_moving_arc.aff","arctap_practice.aff","native_arc_tap.aff"})Check(Chart.Parse(Load(n)).JudgmentUnits>0,n);});
  Test("real independent child mesh and thin trace parent geometry",()=>{var k=New();F(k,1500);track.Refresh(k);var c=k.ArcTaps[0];var mesh=track.ArcTapVisual(c)!;var parent=track.ArcVisual(c.ParentId)!;Check(parent.IsAncestorOf(mesh)&&mesh.Mesh is BoxMesh&&mesh.Visible,"child in parent tree");Check(((BoxMesh)mesh.Mesh).Size.X==180*SpatialTrack.Unit&&parent.GetChildren().OfType<MeshInstance3D>().Any(m=>m!=mesh&&m.MaterialOverride is StandardMaterial3D material&&material.AlbedoColor==new Color("98a4ba")),"distinct child/trace style");});
  Test("child world geometry approaches while target remains Z0",()=>{var k=New();F(k,1000);track.Refresh(k);var c=k.ArcTaps[0];float before=track.ArcTapVisual(c)!.Position.Z;F(k,1500);track.Refresh(k);var p=c.WorldPosition;Check(track.ArcTapVisual(c)!.Position.IsEqualApprox(SpatialTrack.World(p.X,p.Y,p.Z))&&track.ArcTapVisual(c)!.Position.Z>before&&Math.Abs(p.Z)<1&&c.InputTarget.Z==0,"local sample/scrolling parent/input separation");});
  Test("visible child projection selects once in both camera modes",()=>{foreach(bool alternate in new[]{false,true}){track.SetView(alternate);var k=New();F(k,1500);track.Refresh(k);var c=k.ArcTaps[0];var sky=Pick(c);Check(ArcTapSpatial.Matches(c.InputTarget.X,c.InputTarget.Y,sky),"rendered center eligible");k.DownSpatial(4502,42,0,sky);Check(k.Pure==1&&c.Consumed,"first click");k.Up(42);k.DownSpatial(4502,43,0,sky);Check(k.Classifications.Single().Outcome=="guard_consumed"&&k.Pure==1,"same projection duplicate guard");}track.SetView(false);});
  Test("actual changed viewport keeps child projection aligned",()=>{var vp=(SubViewport)track.GetViewport();var container=(SubViewportContainer)vp.GetParent();var previous=vp.Size;bool stretch=container.Stretch;container.Stretch=false;try{foreach(var size in new[]{new Vector2I(610,550),new Vector2I(732,660)})foreach(bool alternate in new[]{false,true}){vp.Size=size;Check(vp.Size==size,"actual resize");track.SetView(alternate);var k=New();F(k,1500);track.Refresh(k);var c=k.ArcTaps[0];var sky=Pick(c);Check(ArcTapSpatial.Matches(c.InputTarget.X,c.InputTarget.Y,sky),"resized child region");k.DownSpatial(4502,42,0,sky);Check(k.Pure==1,"resized hit");}}finally{vp.Size=previous;container.Stretch=stretch;track.SetView(false);}});
  Test("invalid and outside rays cannot create a child judgment",()=>{var k=New();F(k,1500);var bounds=track.GetViewport().GetVisibleRect();foreach(var point in new[]{new Vector2(-1,10),new Vector2(bounds.Size.X+1,10),new Vector2(float.NaN,0)}){Check(!track.PickSky(point,out _),"invalid point rejected");}Check(!SpatialTrack.SkyIntersection(Vector3.One,Vector3.Up,out _)&&!SpatialTrack.SkyIntersection(Vector3.One,Vector3.Back,out _)&&k.Pure==0&&!k.ArcTaps[0].Consumed,"safe no award");});
  Test("held mouse over parent and rendered child does not autojudge",()=>{var k=New();F(k,1000);var c=k.ArcTaps[0];k.DownSpatial(4002,42,0,new SkyContact(c.InputTarget));F(k,1500);k.MoveSpatial(42,0,Pick(c));F(k,1500);track.Refresh(k);Check(!c.Consumed&&k.Pure==0&&!c.Parent.Holding&&c.Parent.Color.Owner==-1&&((StandardMaterial3D)track.ArcTapVisual(c)!.MaterialOverride).AlbedoColor==new Color("ffd36f"),"DOWN only");});
  Test("authoritative hit and miss feedback expires without stale child",()=>{var hit=New();F(hit,1500);var c=hit.ArcTaps[0];hit.DownSpatial(4502,42,0,Pick(c));track.Refresh(hit);var mesh=track.ArcTapVisual(c)!;Check(mesh.Visible&&((StandardMaterial3D)mesh.MaterialOverride).AlbedoColor==new Color("a5f56d"),"hit feedback");F(hit,1751);track.Refresh(hit);Check(!mesh.Visible,"hide consumed feedback");var miss=New();F(miss,1601);track.Refresh(miss);c=miss.ArcTaps[0];mesh=track.ArcTapVisual(c)!;Check(c.Missed&&mesh.Visible&&((StandardMaterial3D)mesh.MaterialOverride).AlbedoColor==new Color("ff6985"),"miss feedback");F(miss,1852);track.Refresh(miss);Check(!mesh.Visible,"hide miss feedback");});
  Test("renderer cannot mutate child parent counters or ownership",()=>{var k=New();F(k,1500);var c=k.ArcTaps[0];string State()=>JsonSerializer.Serialize(new{k.Pure,k.Score,k.Health,k.Combo,k.ContactCount,c.Id,c.ParentId,c.Local,c.WorldPosition,c.InputTarget,c.Consumed,c.Missed,c.Contact,c.ResolvedAt,c.Parent.Color});string before=State();for(int i=0;i<20;i++)track.Refresh(k);Check(before==State(),"read-only presentation");});
  Test("pause60seconds freezes mesh and resume needs fresh DOWN",()=>{var k=New();F(k,1400);track.Refresh(k);var c=k.ArcTaps[0];var mesh=track.ArcTapVisual(c)!;var p=mesh.Position;k.Pause(4402);k.Frame(64402);track.Refresh(k);Check(mesh.Position==p&&!c.Consumed&&k.Pure==0,"frozen");k.Resume(64402);k.Frame(64502);track.Refresh(k);Check(!c.Consumed,"no resume award");k.DownSpatial(64502,42,0,Pick(c));Check(k.Pure==1,"normal click");});
  Test("restart and menu remove old child node and state",()=>{var k=New();F(k,1500);track.Refresh(k);var c=k.ArcTaps[0];var old=track.ArcTapVisual(c)!;k.DownSpatial(4502,42,0,Pick(c));var fresh=New();track.Refresh(fresh);Check(!old.IsInsideTree()&&!ReferenceEquals(old,track.ArcTapVisual(fresh.ArcTaps[0]))&&!fresh.ArcTaps[0].Consumed,"fresh node/state");track.Refresh(null);Check(track.ArcVisualCount==0,"home cleanup");});
  Test("production bridge mixed chart click projection results cleanup",()=>{var clock=new Clock();var session=new GameplaySession(clock);session.Start(Load("arctap_practice.aff"));clock.Milliseconds=3002;session.Frame();for(int e=1;e<=10621;e++){clock.Milliseconds=e+3002;foreach(var tap in session.Core!.Chart.Taps.Where(t=>t.Time==e)){session.Contact(200+tap.Ordinal,tap.Lane,true);session.Contact(200+tap.Ordinal,tap.Lane,false);}session.Frame();if(e==6000){track.Refresh(session.Core);var child=session.Core.ArcTaps[0];session.Pointer(100,0,Pick(child),true);session.Pointer(100,0,null,false);}}track.Refresh(session.Core);Check(session.Core!.Result!.Score==10000005&&session.HeldCount==0&&session.Core.ContactCount==0&&!track.ArcVisual(session.Core.ArcTaps[0].ParentId)!.Visible,"complete reconstructed result");});
  track.Refresh(null);track.SetView(false);File.WriteAllText(Path.Combine(evidenceDir,"arctap-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,humanQualification="PENDING"},new JsonSerializerOptions{WriteIndented=true}));GD.Print($"R008 headless: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");owner.GetTree().Quit(failed==0?0:1);
 }
}
